window.MHD_GLOSSARY_EXPANSION=[{"term":"Acute stress disorder","cat":"Conditions","pron":"uh-KYOOT stress dis-OR-der","def":"A trauma- and stressor-related disorder that can develop after exposure to trauma and includes intrusion, negative mood, dissociation, avoidance, and arousal symptoms lasting from 3 days to 1 month.","aliases":["ASD"],"related":["PTSD","Trauma","Dissociation"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Autism spectrum disorder","cat":"Conditions","pron":"AW-tiz-um SPEK-trum dis-OR-der","def":"A neurodevelopmental condition involving persistent differences in social communication and interaction together with restricted or repetitive patterns of behavior, interests, or sensory experience.","aliases":["autism","ASD"],"related":["Neurodevelopmental disorder","ADHD","Sensory sensitivity"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Avoidant/restrictive food intake disorder","cat":"Conditions","pron":"uh-VOY-dunt ree-STRIK-tiv food IN-tayk dis-OR-der","def":"An eating disorder involving restricted food intake that causes significant nutritional, weight, growth, or functional problems without the body-image disturbance required for anorexia nervosa.","aliases":["ARFID"],"related":["Eating disorder","Anorexia nervosa","Pica"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Body dysmorphic disorder","cat":"Conditions","pron":"BOD-ee dis-MOR-fik dis-OR-der","def":"A condition involving persistent preoccupation with perceived defects or flaws in appearance that are not observable or appear slight to others, along with repetitive behaviors or mental acts.","aliases":["BDD"],"related":["OCD","Eating disorder","Compulsion"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Brief psychotic disorder","cat":"Conditions","pron":"BREEF sy-KOT-ik dis-OR-der","def":"A psychotic disorder involving sudden psychotic symptoms that last at least 1 day but less than 1 month, followed by eventual return toward the previous level of functioning.","aliases":[],"related":["Psychosis","Schizophreniform disorder","Substance-induced psychotic disorder"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Cannabis use disorder","cat":"Conditions","pron":"KAN-uh-bis YOOS dis-OR-der","def":"A substance-use disorder involving a problematic pattern of cannabis use that causes clinically significant impairment or distress.","aliases":["CUD"],"related":["Substance use disorder","Intoxication","Withdrawal"],"route":"","collections":["Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Cyclothymic disorder","cat":"Conditions","pron":"sy-kloh-THY-mik dis-OR-der","def":"A bipolar-spectrum condition involving numerous periods of hypomanic symptoms and depressive symptoms that do not meet full episode criteria, persisting over a long period.","aliases":["cyclothymia"],"related":["Bipolar disorder","Hypomania","Depression"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Delusional disorder","cat":"Conditions","pron":"dih-LOO-zhun-ul dis-OR-der","def":"A psychotic disorder characterized by one or more persistent delusions without the full symptom pattern required for schizophrenia.","aliases":[],"related":["Delusion","Psychosis","Schizophrenia"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Depersonalization/derealization disorder","cat":"Conditions","pron":"dee-per-suh-nuh-lih-ZAY-shun dee-ree-uh-lih-ZAY-shun dis-OR-der","def":"A dissociative disorder involving persistent or recurrent depersonalization, derealization, or both while reality testing remains intact.","aliases":["DPDR"],"related":["Depersonalization","Derealization","Dissociation"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Dissociative identity disorder","cat":"Conditions","pron":"dih-SOH-see-uh-tiv eye-DEN-tih-tee dis-OR-der","def":"A dissociative disorder involving disruption of identity with distinct identity states and gaps in recall that are not consistent with ordinary forgetting.","aliases":["DID"],"related":["Dissociation","Dissociative amnesia","Trauma"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Excoriation disorder","cat":"Conditions","pron":"ek-skor-ee-AY-shun dis-OR-der","def":"A body-focused repetitive behavior disorder involving recurrent skin picking that causes skin lesions and repeated attempts to reduce or stop the behavior.","aliases":["skin-picking disorder"],"related":["OCD","Trichotillomania","Compulsion"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Hoarding disorder","cat":"Conditions","pron":"HOR-ding dis-OR-der","def":"A condition involving persistent difficulty discarding possessions because of a perceived need to save them and distress associated with discarding, leading to clutter that compromises living areas.","aliases":[],"related":["OCD","Compulsion","Executive function"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Illness anxiety disorder","cat":"Conditions","pron":"IL-ness ang-ZY-uh-tee dis-OR-der","def":"A condition involving persistent preoccupation with having or acquiring a serious illness despite minimal or absent somatic symptoms, accompanied by high health anxiety or excessive health-related behavior.","aliases":["health anxiety"],"related":["Somatic symptom disorder","Anxiety","Reassurance seeking"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Intermittent explosive disorder","cat":"Conditions","pron":"in-ter-MIT-ent ek-SPLOH-siv dis-OR-der","def":"A disorder involving recurrent impulsive aggressive outbursts that are disproportionate to the situation and not premeditated.","aliases":["IED"],"related":["Impulse control","Agitation","Conduct disorder"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Narcissistic personality disorder","cat":"Conditions","pron":"nar-suh-SIS-tik per-suh-NAL-ih-tee dis-OR-der","def":"A personality disorder involving a persistent pattern of grandiosity, need for admiration, and difficulty with empathy, expressed across contexts.","aliases":["NPD"],"related":["Personality disorder","Grandiosity","Interpersonal functioning"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Obsessive-compulsive personality disorder","cat":"Conditions","pron":"ub-SESS-iv kum-PUL-siv per-suh-NAL-ih-tee dis-OR-der","def":"A personality disorder involving persistent preoccupation with orderliness, perfectionism, and control that can reduce flexibility and openness.","aliases":["OCPD"],"related":["OCD","Personality disorder","Perfectionism"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"OCPD is not the same as OCD; OCD centers on obsessions and compulsions, while OCPD describes a broader personality pattern.","sources":[],"reviewed":"October 5, 2026"},{"term":"Oppositional defiant disorder","cat":"Conditions","pron":"op-uh-ZISH-uh-nul dih-FY-unt dis-OR-der","def":"A childhood disorder involving a persistent pattern of angry or irritable mood, argumentative or defiant behavior, or vindictiveness toward authority figures beyond expected developmental behavior.","aliases":["ODD"],"related":["Conduct disorder","ADHD","Irritability"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Persistent depressive disorder","cat":"Conditions","pron":"per-SIS-tent dih-PRESS-iv dis-OR-der","def":"A depressive disorder involving depressed mood for much of the day on more days than not over a long duration, together with additional depressive symptoms.","aliases":["PDD","dysthymia"],"related":["Depression","Major depressive disorder","Remission"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Pica","cat":"Conditions","pron":"PIE-kuh","def":"An eating disorder involving persistent eating of nonfood substances that is developmentally inappropriate and not part of a culturally supported practice.","aliases":[],"related":["Eating disorder","ARFID","Medical evaluation"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Premenstrual dysphoric disorder","cat":"Conditions","pron":"pree-MEN-stroo-ul dis-FOR-ik dis-OR-der","def":"A severe cyclical mood disorder in which significant emotional and physical symptoms occur during the premenstrual phase and improve after menstruation begins.","aliases":["PMDD"],"related":["Depression","Mood","Hormonal cycle"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Prolonged grief disorder","cat":"Conditions","pron":"proh-LAWNGD GREEF dis-OR-der","def":"A condition involving persistent, intense grief and preoccupation with a person who died, accompanied by significant distress or impairment beyond expected cultural and social norms for the time since the death.","aliases":["PGD"],"related":["Grief","Depression","Trauma"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Schizophreniform disorder","cat":"Conditions","pron":"skit-soh-FREN-ih-form dis-OR-der","def":"A schizophrenia-spectrum disorder with symptoms similar to schizophrenia lasting at least 1 month but less than 6 months.","aliases":[],"related":["Schizophrenia","Brief psychotic disorder","Psychosis"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Seasonal affective disorder","cat":"Conditions","pron":"SEE-zuh-nul uh-FEK-tiv dis-OR-der","def":"A common term for a recurrent depressive pattern that follows a seasonal schedule. Clinically, it is usually described as major depressive disorder or bipolar disorder with a seasonal pattern.","aliases":["SAD","seasonal depression"],"related":["Depression","Bipolar disorder","Circadian rhythm"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Somatic symptom disorder","cat":"Conditions","pron":"soh-MAT-ik SIMP-tum dis-OR-der","def":"A condition involving one or more distressing physical symptoms together with excessive thoughts, feelings, or behaviors related to those symptoms.","aliases":["SSD"],"related":["Illness anxiety disorder","Anxiety","Medical evaluation"],"route":"condition-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Substance-induced psychotic disorder","cat":"Conditions","pron":"SUB-stents in-DOOST sy-KOT-ik dis-OR-der","def":"Psychosis that develops during or soon after intoxication, withdrawal, or exposure to a substance or medication when the substance is judged to be the cause.","aliases":["substance-induced psychosis"],"related":["Psychosis","Intoxication","Withdrawal"],"route":"condition-guide.html","collections":["Substance Use"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Trichotillomania","cat":"Conditions","pron":"trik-oh-til-oh-MAY-nee-uh","def":"A body-focused repetitive behavior disorder involving recurrent hair pulling that causes hair loss and repeated attempts to decrease or stop the behavior.","aliases":["hair-pulling disorder"],"related":["Excoriation disorder","OCD","Compulsion"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Tourette syndrome","cat":"Conditions","pron":"too-RET SIN-drohm","def":"A neurodevelopmental tic disorder involving multiple motor tics and at least one vocal tic over time.","aliases":["Tourette disorder"],"related":["Tic disorder","Neurodevelopmental disorder","ADHD"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Alogia","cat":"Symptoms","pron":"uh-LOH-jee-uh","def":"Reduced amount or content of speech that can occur as a negative symptom in schizophrenia-spectrum disorders and in other conditions.","aliases":["poverty of speech"],"related":["Negative symptoms","Schizophrenia","Avolition"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Avolition","cat":"Symptoms","pron":"ay-voh-LISH-un","def":"Marked reduction in motivation or initiation of goal-directed activity. It can occur as a negative symptom in schizophrenia and in other psychiatric or neurological conditions.","aliases":["loss of motivation"],"related":["Negative symptoms","Apathy","Schizophrenia"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Circumstantiality","cat":"Symptoms","pron":"sur-kum-stan-shee-AL-ih-tee","def":"A speech pattern that includes excessive or unnecessary detail but eventually returns to the original point.","aliases":["circumstantial speech"],"related":["Tangentiality","Thought disorder","Mental status exam"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Clang association","cat":"Symptoms","pron":"KLANG uh-soh-see-AY-shun","def":"A speech pattern in which words are connected by sound or rhyme rather than by meaning. It can occur in severe mania or psychosis.","aliases":["clang associations"],"related":["Mania","Thought disorder","Disorganized speech"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Dissociative amnesia","cat":"Symptoms","pron":"dih-SOH-see-uh-tiv am-NEE-zhuh","def":"Inability to recall important autobiographical information, usually related to trauma or stress, that is inconsistent with ordinary forgetting.","aliases":[],"related":["Dissociation","Trauma","Dissociative identity disorder"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Echolalia","cat":"Symptoms","pron":"ek-oh-LAY-lee-uh","def":"Repetition of another person's words or phrases. It can occur in several neurodevelopmental, neurological, and psychiatric conditions.","aliases":[],"related":["Autism spectrum disorder","Catatonia","Speech"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Echopraxia","cat":"Symptoms","pron":"ek-oh-PRAK-see-uh","def":"Involuntary imitation of another person's movements. It can occur in catatonia and some neurological or psychiatric conditions.","aliases":[],"related":["Catatonia","Echolalia","Motor symptoms"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Flashback","cat":"Symptoms","pron":"FLASH-bak","def":"A vivid re-experiencing of a traumatic event in which the memory may feel as though it is happening again in the present.","aliases":[],"related":["PTSD","Trauma","Dissociation"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Ideas of reference","cat":"Symptoms","pron":"eye-DEE-uhz of REF-er-ents","def":"A belief or impression that ordinary events, comments, media, or behaviors of others have special personal meaning for oneself.","aliases":["referential thinking"],"related":["Delusion","Paranoia","Psychosis"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Labile affect","cat":"Symptoms","pron":"LAY-bile AF-ekt","def":"Rapidly changing outward emotional expression that may shift noticeably over a short period.","aliases":["emotional lability"],"related":["Affect","Mood","Emotion regulation"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Loose associations","cat":"Symptoms","pron":"LOOS uh-soh-see-AY-shuns","def":"A disorganized speech pattern in which ideas shift from one subject to another with weak, unclear, or illogical connections.","aliases":["loosening of associations"],"related":["Thought disorder","Psychosis","Tangentiality"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Neologism","cat":"Symptoms","pron":"nee-OL-uh-jiz-um","def":"A newly created word or unusual use of a word that has a special meaning to the speaker. In clinical settings, neologisms can be part of disorganized thought or speech.","aliases":[],"related":["Thought disorder","Psychosis","Disorganized speech"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Passive death wish","cat":"Symptoms","pron":"PASS-iv DETH wish","def":"Thoughts that life is not worth living or that one would be better off dead without necessarily having an active suicide plan or intent.","aliases":["passive suicidal ideation"],"related":["Suicidal ideation","Suicide risk assessment","Safety plan"],"route":"crisis-legal.html","collections":["Crisis Terms"],"safety":"Any suicidal thinking deserves attention. If a person may act on suicidal thoughts or cannot stay safe, seek live crisis or emergency help.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Perseveration","cat":"Symptoms","pron":"per-sev-er-AY-shun","def":"Persistent repetition of a word, idea, response, or behavior even after the situation has changed or the response is no longer appropriate.","aliases":[],"related":["Thought disorder","Executive function","Neurocognitive disorder"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Psychomotor agitation","cat":"Symptoms","pron":"sy-koh-MOH-ter aj-ih-TAY-shun","def":"Observable increased movement or restlessness associated with inner tension, such as pacing, hand-wringing, or inability to sit still.","aliases":[],"related":["Agitation","Akathisia","Mania"],"route":"","collections":"","safety":["Hospital Words"],"confused":"","sources":"Akathisia is a specific inner-restlessness syndrome often related to medication; psychomotor agitation is a broader descriptive finding.","reviewed":"October 5, 2026"},{"term":"Psychomotor retardation","cat":"Symptoms","pron":"sy-koh-MOH-ter ree-tar-DAY-shun","def":"Noticeable slowing of movement, speech, or thinking that can occur in severe depression and other medical or psychiatric conditions.","aliases":[],"related":["Depression","Catatonia","Mental status exam"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Tangentiality","cat":"Symptoms","pron":"tan-jen-shee-AL-ih-tee","def":"A speech pattern in which a person moves away from the question or topic and does not return to the original point.","aliases":["tangential speech"],"related":["Circumstantiality","Thought disorder","Loose associations"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Thought blocking","cat":"Symptoms","pron":"THAWT BLOK-ing","def":"A sudden interruption in a train of thought or speech, sometimes experienced as the mind going blank.","aliases":[],"related":["Thought disorder","Psychosis","Mental status exam"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Hyperarousal","cat":"Symptoms","pron":"HY-per uh-ROW-zul","def":"A heightened state of physiological and emotional activation that can include irritability, startle, sleep problems, vigilance, or difficulty relaxing.","aliases":[],"related":["PTSD","Hypervigilance","Anxiety"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"PHQ-9","cat":"Tests & scales","pron":"pee-aitch-cue NINE","def":"A 9-item patient questionnaire widely used to screen for and measure the severity of depressive symptoms. It is a screening and monitoring tool, not a diagnosis by itself.","aliases":["Patient Health Questionnaire-9","PHQ9"],"related":["Depression","Screening test","Suicide risk assessment"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"A PHQ-9 score does not replace a clinical assessment.","sources":[["PHQ Screeners","https://www.phqscreeners.com/"]],"reviewed":"October 5, 2026"},{"term":"GAD-7","cat":"Tests & scales","pron":"gee-ay-dee SEV-en","def":"A 7-item questionnaire commonly used to screen for and measure generalized anxiety symptoms. Results should be interpreted in clinical context.","aliases":["Generalized Anxiety Disorder-7","GAD7"],"related":["Anxiety","Screening test","PHQ-9"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"C-SSRS","cat":"Tests & scales","pron":"see-ess-ess-ar-ESS","def":"The Columbia-Suicide Severity Rating Scale, a structured tool used to assess suicidal thoughts and behavior. It supports risk assessment but does not replace clinical judgment or emergency action when danger is immediate.","aliases":["Columbia Suicide Severity Rating Scale","CSSRS"],"related":["Suicide risk assessment","Suicidal ideation","Safety plan"],"route":"crisis-legal.html","collections":["Tests & Labs","Crisis Terms","Acronym Decoder"],"safety":"If there is immediate danger or inability to stay safe, seek emergency help rather than relying on a score.","confused":"","sources":[["Columbia Lighthouse Project","https://cssrs.columbia.edu/"]],"reviewed":"October 5, 2026"},{"term":"AIMS","cat":"Tests & scales","pron":"aymz","def":"The Abnormal Involuntary Movement Scale, a clinician-rated tool used to detect and monitor abnormal involuntary movements, including tardive dyskinesia.","aliases":["Abnormal Involuntary Movement Scale"],"related":["Tardive dyskinesia","Antipsychotic","Extrapyramidal symptoms"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"ASRS","cat":"Tests & scales","pron":"ay-ess-ar-ESS","def":"The Adult ADHD Self-Report Scale, a questionnaire used to screen for adult ADHD symptoms. Screening results are not a diagnosis and should be considered with developmental history and impairment.","aliases":["Adult ADHD Self-Report Scale"],"related":["ADHD","Screening test","Executive function"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"AUDIT-C","cat":"Tests & scales","pron":"AW-dit SEE","def":"A brief alcohol-use screening questionnaire derived from the Alcohol Use Disorders Identification Test.","aliases":["Alcohol Use Disorders Identification Test-Consumption"],"related":["Alcohol use disorder","Screening test","SBIRT"],"route":"","collections":["Tests & Labs","Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"DAST-10","cat":"Tests & scales","pron":"dast TEN","def":"A brief screening questionnaire used to identify possible problems related to drug use other than alcohol or tobacco.","aliases":["Drug Abuse Screening Test-10","DAST"],"related":["Substance use disorder","Screening test","SBIRT"],"route":"","collections":["Tests & Labs","Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"MDQ","cat":"Tests & scales","pron":"em-dee-CUE","def":"The Mood Disorder Questionnaire, a screening tool intended to identify a history of symptoms associated with bipolar-spectrum conditions. A positive screen is not a diagnosis.","aliases":["Mood Disorder Questionnaire"],"related":["Bipolar disorder","Mania","Screening test"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"MoCA","cat":"Tests & scales","pron":"MOH-kuh","def":"The Montreal Cognitive Assessment, a brief cognitive screening tool used to examine areas such as memory, attention, language, visuospatial skills, and executive function.","aliases":["Montreal Cognitive Assessment"],"related":["Cognitive screening","Mild cognitive impairment","Neurocognitive disorder"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"MMSE","cat":"Tests & scales","pron":"em-em-ess-EE","def":"The Mini-Mental State Examination, a brief structured cognitive assessment used in some settings to screen and monitor cognitive impairment.","aliases":["Mini-Mental State Examination"],"related":["Cognitive screening","Dementia","MoCA"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"PCL-5","cat":"Tests & scales","pron":"pee-see-el FIVE","def":"The PTSD Checklist for DSM-5, a 20-item self-report measure used to assess PTSD symptoms and monitor change. Diagnosis requires appropriate clinical assessment.","aliases":["PTSD Checklist for DSM-5","PCL5"],"related":["PTSD","Screening test","Trauma"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[["VA National Center for PTSD","https://www.ptsd.va.gov/professional/assessment/adult-sr/ptsd-checklist.asp"]],"reviewed":"October 5, 2026"},{"term":"PANSS","cat":"Tests & scales","pron":"pans","def":"The Positive and Negative Syndrome Scale, a clinician-rated instrument used mainly in research and specialty care to measure symptom severity in schizophrenia-spectrum illness.","aliases":["Positive and Negative Syndrome Scale"],"related":["Schizophrenia","Positive symptoms","Negative symptoms"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"YMRS","cat":"Tests & scales","pron":"why-em-ar-ESS","def":"The Young Mania Rating Scale, a clinician-rated scale used to measure the severity of manic symptoms.","aliases":["Young Mania Rating Scale"],"related":["Mania","Bipolar disorder","Mood episode"],"route":"condition-guide.html","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"HAM-D","cat":"Tests & scales","pron":"ham-DEE","def":"The Hamilton Depression Rating Scale, a clinician-administered scale used to measure depressive symptom severity, especially in research and specialty care.","aliases":["Hamilton Depression Rating Scale","HDRS"],"related":["Depression","PHQ-9","Clinical trial"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Clinical Global Impression","cat":"Tests & scales","pron":"KLIN-ih-kul GLOH-bul im-PRESH-un","def":"A brief clinician rating framework used in research and practice to summarize illness severity and change over time.","aliases":["CGI"],"related":["Outcome measure","Clinical trial","Severity"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Adverse Childhood Experiences","cat":"Tests & scales","pron":"AD-vers CHILD-hood ek-SPEER-ee-en-siz","def":"Potentially traumatic experiences occurring before age 18, such as abuse, neglect, or household adversity. ACE scores describe exposure history and do not determine an individual's future mental health.","aliases":["ACEs","ACE score"],"related":["Trauma","Risk factor","Protective factor"],"route":"","collections":["Tests & Labs","Acronym Decoder"],"safety":"","confused":"An ACE score is not a diagnosis and should not be used to predict an individual outcome with certainty.","sources":[],"reviewed":"October 5, 2026"},{"term":"Complete blood count","cat":"Tests & labs","pron":"kum-PLEET blud count","def":"A blood test that measures major blood-cell types, including red blood cells, white blood cells, and platelets. Some psychiatric medications require CBC monitoring.","aliases":["CBC"],"related":["ANC","Clozapine","Platelets"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Absolute neutrophil count","cat":"Tests & labs","pron":"AB-suh-loot NOO-troh-fil count","def":"A calculation estimating the number of neutrophils, a type of white blood cell. ANC monitoring is particularly important with clozapine because of severe neutropenia risk.","aliases":["ANC"],"related":["Clozapine","CBC","Neutropenia"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"Severe neutropenia can increase infection risk and requires prompt clinical management.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Comprehensive metabolic panel","cat":"Tests & labs","pron":"kom-prih-HEN-siv met-uh-BOL-ik PAN-ul","def":"A blood-test panel that commonly includes electrolytes, kidney-related measures, glucose, proteins, and liver-related tests.","aliases":["CMP"],"related":["Electrolytes","Creatinine","Liver enzymes"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Basic metabolic panel","cat":"Tests & labs","pron":"BAY-sik met-uh-BOL-ik PAN-ul","def":"A blood-test panel that commonly includes electrolytes, glucose, and kidney-related measures.","aliases":["BMP"],"related":["Electrolytes","Creatinine","Glucose"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Creatinine","cat":"Tests & labs","pron":"kree-AT-ih-neen","def":"A blood measurement commonly used with other information to estimate kidney function. Kidney function is important for some psychiatric medications, including lithium.","aliases":[],"related":["eGFR","Lithium","Kidney function"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"eGFR","cat":"Tests & labs","pron":"ee-jee-eff-AR","def":"Estimated glomerular filtration rate, a calculated measure used to estimate kidney filtration. It can help guide medication safety and dosing for drugs affected by kidney function.","aliases":["estimated glomerular filtration rate"],"related":["Creatinine","Kidney function","Lithium"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"TSH","cat":"Tests & labs","pron":"tee-ess-AYCH","def":"Thyroid-stimulating hormone, a blood test commonly used to evaluate thyroid function. Thyroid disorders can affect mood, energy, cognition, and medication management.","aliases":["thyroid-stimulating hormone"],"related":["Thyroid","Lithium","Depression"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Hemoglobin A1C","cat":"Tests & labs","pron":"HEE-muh-gloh-bin ay-one-SEE","def":"A blood test that reflects average blood glucose over roughly the previous 2 to 3 months. It may be monitored when medications can affect metabolic health.","aliases":["A1C","HbA1c"],"related":["Glucose","Metabolic monitoring","Antipsychotic"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Lipid panel","cat":"Tests & labs","pron":"LIP-id PAN-ul","def":"A blood test that measures cholesterol and triglyceride levels. It is often part of metabolic monitoring for medications associated with weight or lipid changes.","aliases":["cholesterol panel"],"related":["Triglycerides","Metabolic monitoring","Antipsychotic"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Prolactin","cat":"Tests & labs","pron":"proh-LAK-tin","def":"A hormone that can increase with certain medications, particularly some antipsychotics. Elevated prolactin can affect menstrual cycles, sexual function, breast tissue, or bone health.","aliases":[],"related":["Antipsychotic","Hormone","Medication side effect"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"ECG","cat":"Tests & labs","pron":"ee-see-JEE","def":"Electrocardiogram, a test that records the heart's electrical activity. Some medications or medical conditions make ECG monitoring relevant.","aliases":["EKG","electrocardiogram"],"related":["QTc interval","Heart rhythm","Medication monitoring"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"QTc interval","cat":"Tests & labs","pron":"cue-tee-see IN-ter-vul","def":"A heart-rhythm measurement derived from an ECG and corrected for heart rate. Some medications can prolong QTc and increase the risk of dangerous arrhythmias in susceptible people.","aliases":["corrected QT interval"],"related":["ECG","Ziprasidone","Citalopram"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"Marked QT prolongation can be medically significant; interpretation belongs with a clinician.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Serum lithium level","cat":"Tests & labs","pron":"SEER-um LITH-ee-um LEV-ul","def":"A blood measurement of lithium concentration used to help guide dosing and reduce toxicity risk.","aliases":["lithium level"],"related":["Lithium","Therapeutic range","Lithium toxicity"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"Lithium has a narrow therapeutic range. Symptoms of toxicity require prompt medical attention.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Valproate level","cat":"Tests & labs","pron":"VAL-proh-ayt LEV-ul","def":"A blood concentration measurement sometimes used to help guide valproate or divalproex treatment and assess adherence, effectiveness, or toxicity risk.","aliases":["valproic acid level"],"related":["Divalproex","Therapeutic drug monitoring","Liver enzymes"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Liver enzymes","cat":"Tests & labs","pron":"LIV-er EN-zymes","def":"Blood tests such as ALT and AST that can help evaluate liver injury or inflammation. They may be monitored with medications that affect the liver.","aliases":["AST","ALT","hepatic panel"],"related":["Valproate","Kava","CMP"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Urine drug screen","cat":"Tests & labs","pron":"YOOR-in drug SKREEN","def":"A test that looks for evidence of selected substances or drug classes in urine. Screening tests can have false positives or negatives and may require confirmatory testing.","aliases":["UDS","toxicology screen","tox screen"],"related":["Substance use","Confirmatory test","Intoxication"],"route":"","collections":["Tests & Labs","Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Pregnancy test","cat":"Tests & labs","pron":"PREG-nun-see test","def":"A test for pregnancy that may be relevant before or during treatment with medications that can affect pregnancy or fetal development.","aliases":["hCG test"],"related":["Valproate","Medication risk","Informed consent"],"route":"medication-guide.html","collections":["Tests & Labs","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Adverse drug reaction","cat":"Medication & side effects","pron":"AD-vers drug ree-AK-shun","def":"An unwanted or harmful response associated with a medication. The term can include reactions more serious than ordinary expected side effects.","aliases":["ADR"],"related":["Side effect","Drug allergy","Medication interaction"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Augmentation","cat":"Medication & side effects","pron":"awg-men-TAY-shun","def":"Adding a second treatment to an existing treatment to improve response rather than replacing the original treatment.","aliases":["augmentation strategy"],"related":["Combination therapy","Monotherapy","Treatment-resistant depression"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Contraindication","cat":"Medication & side effects","pron":"kon-truh-in-dih-KAY-shun","def":"A condition or circumstance in which a particular treatment or medication should not be used, or should be avoided unless special circumstances justify it.","aliases":[],"related":["Drug interaction","Precaution","FDA labeling"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Cross-taper","cat":"Medication & side effects","pron":"KROSS TAY-per","def":"A medication-switching strategy in which one medication is gradually reduced while another is gradually increased. The approach is not appropriate for every drug combination.","aliases":["cross taper"],"related":["Taper","Withdrawal","Medication switch"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"Cross-tapering can create interaction or withdrawal risks and should follow an individualized prescriber plan.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"CYP450","cat":"Medication & side effects","pron":"see-why-pee four-fifty","def":"Cytochrome P450 refers to a family of liver enzymes involved in the metabolism of many medications. Drugs that inhibit or induce these enzymes can change medication levels.","aliases":["cytochrome P450"],"related":["Drug interaction","Pharmacokinetics","Metabolism"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Depot injection","cat":"Medication & side effects","pron":"DEE-poh in-JEK-shun","def":"A long-acting injectable medication designed to release medicine over an extended period rather than requiring daily oral dosing.","aliases":["LAI","long-acting injectable"],"related":["Antipsychotic","Adherence","Injection"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Discontinuation syndrome","cat":"Medication & side effects","pron":"dis-kon-tin-yoo-AY-shun SIN-drohm","def":"Symptoms that can occur after stopping or rapidly reducing certain medications, including some antidepressants. Symptoms vary by drug and are not the same as return of the underlying illness.","aliases":["antidepressant discontinuation syndrome"],"related":["Withdrawal","Taper","Relapse"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"Discontinuation symptoms can resemble relapse; timing, symptom pattern, and medication history help clinicians distinguish them.","sources":[],"reviewed":"October 5, 2026"},{"term":"Drug-drug interaction","cat":"Medication & side effects","pron":"drug drug in-ter-AK-shun","def":"A situation in which one medication changes the effects, levels, or risks of another medication.","aliases":["DDI","medication interaction"],"related":["CYP450","Contraindication","Serotonin syndrome"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Half-life","cat":"Medication & side effects","pron":"HAF life","def":"The time required for the amount or concentration of a drug in the body to decrease by about half. Half-life helps influence dosing intervals and how long a drug may remain in the body.","aliases":[],"related":["Steady state","Pharmacokinetics","Withdrawal"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medication adherence","cat":"Medication & side effects","pron":"med-ih-KAY-shun ad-HEER-ents","def":"How closely a person's actual medication use matches the agreed treatment plan. The term is preferred to language that frames every difference as disobedience.","aliases":["adherence","medication compliance"],"related":["Shared decision-making","Long-acting injectable","Treatment plan"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Monotherapy","cat":"Medication & side effects","pron":"mon-oh-THAIR-uh-pee","def":"Treatment using one medication or one main therapeutic approach rather than combining multiple treatments.","aliases":[],"related":["Polypharmacy","Augmentation","Combination therapy"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Pharmacodynamics","cat":"Medication & side effects","pron":"far-muh-koh-dy-NAM-iks","def":"What a drug does to the body, including its effects on receptors, signaling systems, and physiological functions.","aliases":["PD"],"related":["Pharmacokinetics","Mechanism of action","Receptor"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Pharmacokinetics","cat":"Medication & side effects","pron":"far-muh-koh-kih-NET-iks","def":"What the body does to a drug through absorption, distribution, metabolism, and elimination.","aliases":["PK"],"related":["Half-life","CYP450","Steady state"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Polypharmacy","cat":"Medication & side effects","pron":"pol-ee-FAR-muh-see","def":"Use of multiple medications at the same time. Polypharmacy can be appropriate, but it can also increase complexity, interaction risk, and side-effect burden.","aliases":[],"related":["Monotherapy","Drug-drug interaction","Medication reconciliation"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"PRN","cat":"Medication & side effects","pron":"pee-ar-EN","def":"An abbreviation from the Latin pro re nata meaning a medication is taken as needed rather than on a fixed schedule, within the prescriber's instructions.","aliases":["as needed medication","pro re nata"],"related":["Medication order","Dose","Schedule"],"route":"medication-guide.html","collections":["Medication Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Steady state","cat":"Medication & side effects","pron":"STED-ee state","def":"A point during repeated dosing when the amount of drug entering the body is roughly balanced by the amount being eliminated, producing a relatively stable average concentration.","aliases":[],"related":["Half-life","Pharmacokinetics","Therapeutic drug monitoring"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Therapeutic range","cat":"Medication & side effects","pron":"thair-uh-PYOO-tik raynj","def":"A concentration range in which a medication is more likely to be effective without unacceptable toxicity. Only some medications use routine blood-level targets.","aliases":["therapeutic window"],"related":["Lithium level","Valproate level","Therapeutic drug monitoring"],"route":"medication-guide.html","collections":["Medication Words","Tests & Labs"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medication reconciliation","cat":"Medication & side effects","pron":"med-ih-KAY-shun rek-un-sil-ee-AY-shun","def":"The process of creating and verifying an accurate medication list, especially during transitions such as hospital admission, discharge, or a new clinician visit.","aliases":["med rec"],"related":["Discharge planning","Polypharmacy","Medication list"],"route":"appointment-builder.html","collections":["Medication Words","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Discharge planning","cat":"Hospital & systems","pron":"dis-CHARJ PLAN-ing","def":"The process of preparing for a safe transition out of a hospital or intensive level of care, including medications, appointments, safety planning, transportation, housing, and follow-up needs.","aliases":["discharge plan"],"related":["Aftercare","Warm handoff","Medication reconciliation"],"route":"crisis-legal.html","collections":["Hospital Words","Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Warm handoff","cat":"Hospital & systems","pron":"WORM HAND-off","def":"A transition in which one provider or service directly connects a person with the next provider or service rather than simply giving a phone number or referral list.","aliases":[],"related":["Discharge planning","Care coordination","Aftercare"],"route":"crisis-legal.html","collections":["Hospital Words","Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medical clearance","cat":"Hospital & systems","pron":"MED-ih-kul KLEER-ents","def":"A commonly used but imprecise term for the medical evaluation performed before or during psychiatric care to identify urgent medical causes, injuries, intoxication, withdrawal, or other conditions requiring medical treatment.","aliases":[],"related":["Emergency evaluation","Delirium","Toxicology screen"],"route":"crisis-legal.html","collections":["Hospital Words"],"safety":"","confused":"Medical assessment should not be reduced to a single test; what is needed depends on symptoms, history, exam, and setting.","sources":[],"reviewed":"October 5, 2026"},{"term":"Observation status","cat":"Hospital & systems","pron":"ob-zur-VAY-shun STAY-tus","def":"A short-term hospital or emergency status used to monitor, assess, or stabilize a person while determining the next level of care. Exact meaning depends on the facility and payer rules.","aliases":["psychiatric observation"],"related":["Emergency evaluation","Inpatient care","Crisis stabilization"],"route":"crisis-legal.html","collections":["Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Seclusion","cat":"Hospital & systems","pron":"see-KLOO-zhun","def":"Involuntary confinement of a person alone in a room or area from which they are physically prevented from leaving. Health-care use is tightly regulated and generally limited to safety situations.","aliases":[],"related":["Restraint","Patient rights","Least restrictive alternative"],"route":"crisis-legal.html","collections":["Hospital Words","Crisis Terms"],"safety":"Seclusion carries safety and rights implications and should only be used under applicable clinical and legal standards.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Restraint","cat":"Hospital & systems","pron":"ree-STRAYNT","def":"A physical, mechanical, or sometimes medication-related intervention that restricts movement or behavior. Health-care use is regulated and generally reserved for situations involving immediate safety risks.","aliases":[],"related":["Seclusion","Patient rights","Least restrictive alternative"],"route":"crisis-legal.html","collections":["Hospital Words","Crisis Terms"],"safety":"Restraint can cause physical and psychological harm and is subject to strict clinical and legal requirements.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Least restrictive alternative","cat":"Hospital & systems","pron":"LEEST ree-STRIK-tiv awl-TER-nuh-tiv","def":"The principle that care or legal intervention should use the least restrictive option that can safely and effectively meet the person's needs when the law requires that consideration.","aliases":["least restrictive setting"],"related":["Involuntary commitment","Outpatient care","Patient rights"],"route":"crisis-legal.html","collections":["Hospital Words","Legal Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Involuntary medication","cat":"Hospital & systems","pron":"in-VOL-un-tair-ee med-ih-KAY-shun","def":"Medication administered without a person's consent under specific emergency, legal, or institutional authority. Rules vary significantly by jurisdiction and setting.","aliases":["forced medication"],"related":["Capacity","Court-ordered treatment","Informed consent"],"route":"crisis-legal.html","collections":["Hospital Words","Legal Words"],"safety":"The legal standard varies by state and setting. Current local law and hospital rights procedures should be checked.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Court-ordered treatment","cat":"Hospital & systems","pron":"KORT OR-derd TREET-ment","def":"Treatment required by a court order under a specific legal process. The authority, duration, and available rights depend on the jurisdiction and type of proceeding.","aliases":[],"related":["Involuntary commitment","Assisted outpatient treatment","Patient rights"],"route":"state-law.html","collections":["Hospital Words","Legal Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Assisted outpatient treatment","cat":"Hospital & systems","pron":"uh-SIS-tid OUT-pay-shent TREET-ment","def":"A court-ordered outpatient mental-health treatment framework used in some jurisdictions for people who meet specific statutory criteria.","aliases":["AOT","outpatient commitment"],"related":["Court-ordered treatment","Involuntary commitment","State law"],"route":"state-law.html","collections":["Hospital Words","Legal Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Aftercare","cat":"Hospital & systems","pron":"AF-ter-kair","def":"Follow-up care and support arranged after hospitalization, residential treatment, or another intensive service.","aliases":["continuing care"],"related":["Discharge planning","Warm handoff","Outpatient care"],"route":"crisis-legal.html","collections":["Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Step-down care","cat":"Hospital & systems","pron":"STEP-down kair","def":"A lower-intensity level of care used after a more intensive service, such as moving from inpatient treatment to PHP, IOP, or standard outpatient care.","aliases":[],"related":["PHP","IOP","Discharge planning"],"route":"treatment-guide.html","collections":["Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Mobile crisis team","cat":"Hospital & systems","pron":"MOH-bul KRY-sis teem","def":"A team that can respond in the community to behavioral-health crises, assess safety and needs, provide short-term intervention, and connect people with services.","aliases":["mobile crisis response"],"related":["988","Crisis stabilization","Emergency evaluation"],"route":"crisis-legal.html","collections":["Crisis Terms","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Crisis residential","cat":"Hospital & systems","pron":"KRY-sis rez-ih-DEN-shul","def":"A short-term, nonhospital residential service intended to support people during a behavioral-health crisis when that level of care is clinically appropriate and available.","aliases":["crisis residence"],"related":["Crisis stabilization","Inpatient care","Respite"],"route":"crisis-legal.html","collections":["Crisis Terms","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Peer respite","cat":"Hospital & systems","pron":"PEER RES-pit","def":"A voluntary, short-term, peer-supported alternative or complement to traditional crisis services available in some communities.","aliases":[],"related":["Peer support","Crisis residential","Recovery"],"route":"","collections":["Crisis Terms","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Collateral information","cat":"Hospital & systems","pron":"kuh-LAT-er-ul in-for-MAY-shun","def":"Information about a person's symptoms, behavior, history, or functioning provided by someone other than the patient, such as family, caregivers, schools, or other clinicians.","aliases":["collateral history"],"related":["Family psychoeducation","Release of information","Baseline"],"route":"family-caregiver.html","collections":["Family & Caregiver","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Utilization review","cat":"Hospital & systems","pron":"yoo-tuh-lih-ZAY-shun ree-VYOO","def":"A process used by health plans or health-care organizations to evaluate whether requested or ongoing services meet coverage or medical-necessity criteria.","aliases":["UR"],"related":["Prior authorization","Medical necessity","Appeal"],"route":"","collections":["Insurance & Access","Hospital Words","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Prior authorization","cat":"Insurance & access","pron":"PRY-or aw-thor-ih-ZAY-shun","def":"A health-plan requirement that approval be obtained before certain medications, tests, or services are covered.","aliases":["prior auth","PA"],"related":["Formulary","Utilization review","Appeal"],"route":"","collections":["Insurance & Access","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medical necessity","cat":"Insurance & access","pron":"MED-ih-kul nuh-SESS-ih-tee","def":"A coverage concept used by health plans to determine whether a service or treatment meets defined clinical and benefit criteria. Definitions vary by plan and law.","aliases":[],"related":["Prior authorization","Utilization review","Appeal"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Formulary","cat":"Insurance & access","pron":"FOR-myuh-lair-ee","def":"A health plan's list of covered prescription drugs, often organized into tiers with different cost-sharing or authorization rules.","aliases":["drug formulary"],"related":["Prior authorization","Copay","Step therapy"],"route":"","collections":["Insurance & Access","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Step therapy","cat":"Insurance & access","pron":"STEP THAIR-uh-pee","def":"A coverage rule requiring a person to try one or more preferred treatments before the plan covers another treatment, unless an exception is granted.","aliases":["fail first"],"related":["Prior authorization","Formulary","Appeal"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"In-network","cat":"Insurance & access","pron":"IN NET-wurk","def":"A provider or facility that has a contract with a health plan to provide covered services under negotiated terms.","aliases":[],"related":["Out-of-network","Copay","Deductible"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Out-of-network","cat":"Insurance & access","pron":"OUT of NET-wurk","def":"A provider or facility that does not have a contract with a person's health plan. Coverage and cost can differ substantially from in-network care.","aliases":[],"related":["In-network","Balance billing","Coinsurance"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Deductible","cat":"Insurance & access","pron":"dih-DUK-tuh-bul","def":"The amount a person generally pays for covered services before the health plan begins paying according to the plan's rules.","aliases":[],"related":["Copay","Coinsurance","Out-of-pocket maximum"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Copay","cat":"Insurance & access","pron":"KOH-pay","def":"A fixed amount a person pays for a covered health-care service or prescription under a health plan.","aliases":["copayment"],"related":["Coinsurance","Deductible","Formulary"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Coinsurance","cat":"Insurance & access","pron":"koh-in-SHUR-ents","def":"The percentage of the allowed cost for a covered service that a person pays after applicable plan rules are met.","aliases":[],"related":["Copay","Deductible","Out-of-pocket maximum"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Explanation of Benefits","cat":"Insurance & access","pron":"ek-spluh-NAY-shun of BEN-uh-fits","def":"A statement from a health plan showing how a claim was processed, what the provider charged, what the plan allowed or paid, and what the member may owe. It is not itself a bill.","aliases":["EOB"],"related":["Claim","Deductible","Appeal"],"route":"","collections":["Insurance & Access","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Appeal","cat":"Insurance & access","pron":"uh-PEEL","def":"A formal request to review or overturn a health-plan decision, such as a denial of coverage or authorization.","aliases":["insurance appeal"],"related":["Denial","Prior authorization","External review"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Grievance","cat":"Insurance & access","pron":"GREE-vunts","def":"A formal complaint process used for concerns about care, service, rights, or health-plan administration that may be separate from a coverage appeal.","aliases":[],"related":["Appeal","Patient rights","Complaint"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Mental health parity","cat":"Insurance & access","pron":"MEN-tul HELTH PAIR-ih-tee","def":"Legal requirements intended to prevent certain health plans from applying more restrictive financial requirements or treatment limitations to mental-health and substance-use benefits than to comparable medical and surgical benefits.","aliases":["behavioral health parity"],"related":["Insurance","Substance use disorder","Appeal"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medicaid","cat":"Insurance & access","pron":"MED-ih-kayd","def":"A joint federal-state health coverage program for eligible people with low income and certain other qualifying circumstances. Benefits and administration vary by state.","aliases":[],"related":["Medicare","CHIP","Insurance"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medicare","cat":"Insurance & access","pron":"MED-ih-kair","def":"A federal health insurance program primarily for people age 65 or older and certain younger people with disabilities or qualifying conditions.","aliases":[],"related":["Medicaid","Part D","Insurance"],"route":"","collections":["Insurance & Access"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"211","cat":"Insurance & access","pron":"two-one-one","def":"A U.S. information and referral service available in many areas that can help connect people with local resources such as housing, food, utilities, health care, and social services.","aliases":["2-1-1"],"related":["Community resources","988","Case management"],"route":"","collections":["Insurance & Access","Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Acceptance and Commitment Therapy","cat":"Treatment & care","pron":"ak-SEP-tents and kuh-MIT-ment THAIR-uh-pee","def":"A psychotherapy that uses acceptance, mindfulness, and behavior-change strategies to help people act in line with personally meaningful values.","aliases":["ACT"],"related":["Mindfulness","Psychotherapy","Values"],"route":"treatment-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"ACT can also mean Assertive Community Treatment; context matters.","sources":[],"reviewed":"October 5, 2026"},{"term":"Assertive Community Treatment","cat":"Treatment & care","pron":"uh-SUR-tiv kuh-MYOO-nih-tee TREET-ment","def":"An intensive, team-based community treatment model for people with serious mental illness who need substantial support to live in the community.","aliases":["ACT team"],"related":["Case management","Serious mental illness","Supported employment"],"route":"treatment-guide.html","collections":["Hospital Words","Acronym Decoder"],"safety":"","confused":"ACT can also mean Acceptance and Commitment Therapy; context matters.","sources":[],"reviewed":"October 5, 2026"},{"term":"Behavioral activation","cat":"Treatment & care","pron":"bee-HAY-vyer-ul ak-tih-VAY-shun","def":"A treatment strategy that helps people gradually increase meaningful, rewarding, or necessary activities to reduce avoidance and improve functioning, commonly used in depression treatment.","aliases":[],"related":["Depression","CBT","Anhedonia"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Contingency management","cat":"Treatment & care","pron":"kun-TIN-jen-see MAN-ij-ment","def":"A behavioral treatment that uses structured incentives to reinforce specific recovery behaviors, with strong evidence for some substance-use disorders.","aliases":[],"related":["Substance use disorder","Behavior therapy","Recovery"],"route":"treatment-guide.html","collections":["Substance Use"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Exposure therapy","cat":"Treatment & care","pron":"ek-SPOH-zher THAIR-uh-pee","def":"A treatment approach that helps people gradually and systematically face feared memories, sensations, objects, or situations so fear and avoidance can decrease over time.","aliases":[],"related":["ERP","Prolonged Exposure","Phobia"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Group therapy","cat":"Treatment & care","pron":"GROOP THAIR-uh-pee","def":"Psychotherapy delivered to multiple participants together, usually led by one or more trained clinicians and organized around shared treatment goals.","aliases":[],"related":["Psychotherapy","Peer support","Support group"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Medication management","cat":"Treatment & care","pron":"med-ih-KAY-shun MAN-ij-ment","def":"Clinical care focused on selecting, monitoring, adjusting, and reviewing medications, including effectiveness, side effects, interactions, adherence, and relevant tests.","aliases":[],"related":["Psychiatrist","Shared decision-making","Medication reconciliation"],"route":"medication-guide.html","collections":["Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Mentalization-based therapy","cat":"Treatment & care","pron":"men-tuh-lih-ZAY-shun bayst THAIR-uh-pee","def":"A structured psychotherapy that aims to strengthen the ability to understand one's own and other people's mental states, particularly under emotional stress.","aliases":["MBT"],"related":["Mentalization","Borderline personality disorder","Psychotherapy"],"route":"treatment-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Motivational interviewing","cat":"Treatment & care","pron":"moh-tih-VAY-shun-ul IN-ter-vyoo-ing","def":"A collaborative counseling approach that helps people explore ambivalence and strengthen their own motivation and commitment to change.","aliases":["MI"],"related":["Substance use disorder","Shared decision-making","Behavior change"],"route":"treatment-guide.html","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Psychoeducation","cat":"Treatment & care","pron":"sy-koh-ed-yuh-KAY-shun","def":"Structured education about a condition, symptoms, treatment, coping, relapse prevention, and available supports for patients, families, or both.","aliases":[],"related":["Family psychoeducation","Relapse prevention","Shared decision-making"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Supportive psychotherapy","cat":"Treatment & care","pron":"suh-POR-tiv sy-koh-THAIR-uh-pee","def":"A psychotherapy approach that emphasizes emotional support, coping, problem-solving, self-esteem, and maintaining or improving functioning.","aliases":[],"related":["Psychotherapy","Coping skill","Therapeutic alliance"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Supported employment","cat":"Treatment & care","pron":"suh-POR-tid em-PLOY-ment","def":"Services that help people with disabilities or serious mental illness obtain and maintain competitive employment with individualized support.","aliases":[],"related":["Recovery","Assertive Community Treatment","Work accommodation"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Supported education","cat":"Treatment & care","pron":"suh-POR-tid ed-yuh-KAY-shun","def":"Services that help people with mental-health conditions pursue education through individualized planning, coordination, and practical support.","aliases":[],"related":["Recovery","School accommodation","Coordinated Specialty Care"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Therapeutic alliance","cat":"Treatment & care","pron":"thair-uh-PYOO-tik uh-LY-ents","def":"The collaborative working relationship between a patient and clinician, including trust, agreement on goals, and agreement on how treatment will proceed.","aliases":["working alliance"],"related":["Psychotherapy","Shared decision-making","Engagement"],"route":"treatment-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Alcohol use disorder","cat":"Substance use","pron":"AL-kuh-hawl YOOS dis-OR-der","def":"A substance-use disorder involving a problematic pattern of alcohol use that leads to clinically significant impairment or distress.","aliases":["AUD"],"related":["Withdrawal","Intoxication","Recovery"],"route":"","collections":["Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Opioid use disorder","cat":"Substance use","pron":"OH-pee-oyd YOOS dis-OR-der","def":"A substance-use disorder involving a problematic pattern of opioid use that causes clinically significant impairment or distress.","aliases":["OUD"],"related":["Buprenorphine","Methadone","Naloxone"],"route":"","collections":["Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Stimulant use disorder","cat":"Substance use","pron":"STIM-yuh-lent YOOS dis-OR-der","def":"A substance-use disorder involving a problematic pattern of stimulant use, such as cocaine or methamphetamine, that causes significant impairment or distress.","aliases":[],"related":["Substance use disorder","Intoxication","Withdrawal"],"route":"","collections":["Substance Use"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Intoxication","cat":"Substance use","pron":"in-tok-sih-KAY-shun","def":"Temporary physical, cognitive, emotional, or behavioral effects caused by recent use of a substance.","aliases":[],"related":["Withdrawal","Overdose","Substance use disorder"],"route":"","collections":["Substance Use"],"safety":"Severe intoxication can be a medical emergency, especially when breathing, consciousness, temperature, heart rhythm, or severe agitation are affected.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Overdose","cat":"Substance use","pron":"OH-ver-dohs","def":"Exposure to a drug or substance in an amount that produces serious toxicity and can cause loss of consciousness, breathing problems, seizures, heart problems, or death.","aliases":[],"related":["Naloxone","Intoxication","911"],"route":"crisis-legal.html","collections":["Substance Use","Crisis Terms"],"safety":"Suspected overdose is an emergency. In the U.S., call 911 and use naloxone when opioid overdose is suspected and naloxone is available.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Naloxone","cat":"Substance use","pron":"nuh-LOK-sohn","def":"A medication that can rapidly reverse opioid overdose by blocking opioid effects at receptors. It is safe to give when opioid overdose is suspected even if opioids are not ultimately the cause.","aliases":["Narcan"],"related":["Opioid use disorder","Overdose","Harm reduction"],"route":"","collections":["Substance Use","Crisis Terms"],"safety":"Opioid overdose can recur after naloxone wears off; emergency medical evaluation is still important.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Buprenorphine","cat":"Substance use","pron":"byoo-preh-NOR-feen","def":"A medication used to treat opioid use disorder and, in some formulations, pain. For opioid use disorder it reduces withdrawal and cravings and lowers overdose risk when used as prescribed.","aliases":["Suboxone component"],"related":["Opioid use disorder","Methadone","MOUD"],"route":"","collections":["Substance Use","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Methadone","cat":"Substance use","pron":"METH-uh-dohn","def":"A long-acting opioid medication used for opioid use disorder in regulated treatment programs and also used for pain in other settings.","aliases":[],"related":["Opioid use disorder","Buprenorphine","MOUD"],"route":"","collections":["Substance Use","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Naltrexone","cat":"Substance use","pron":"nal-TREK-sohn","def":"An opioid-receptor antagonist used in certain formulations to help treat alcohol use disorder or opioid use disorder after appropriate opioid-free preparation.","aliases":[],"related":["Alcohol use disorder","Opioid use disorder","MOUD"],"route":"","collections":["Substance Use","Medication Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"MOUD","cat":"Substance use","pron":"em-oh-you-DEE","def":"Medication for opioid use disorder, an evidence-based treatment category that includes buprenorphine, methadone, and naltrexone.","aliases":["medications for opioid use disorder","MAT"],"related":["Buprenorphine","Methadone","Naltrexone"],"route":"","collections":["Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"SBIRT","cat":"Substance use","pron":"ess-berrt","def":"Screening, Brief Intervention, and Referral to Treatment, a public-health approach for identifying risky substance use and connecting people with appropriate intervention or treatment.","aliases":["Screening Brief Intervention and Referral to Treatment"],"related":["AUDIT-C","DAST-10","Substance use disorder"],"route":"","collections":["Substance Use","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Absolute risk","cat":"Research & evidence","pron":"AB-suh-loot risk","def":"The actual probability of an outcome occurring in a group over a specified period, often expressed as a percentage or rate.","aliases":[],"related":["Relative risk","Number needed to treat","Risk difference"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Bias","cat":"Research & evidence","pron":"BY-us","def":"A systematic influence that can distort study design, data collection, analysis, interpretation, or publication and lead results away from the truth.","aliases":[],"related":["Confounding","Randomization","Blinding"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Blinding","cat":"Research & evidence","pron":"BLYND-ing","def":"A research method in which participants, investigators, outcome assessors, or some combination do not know which treatment a participant received, helping reduce certain biases.","aliases":["masking"],"related":["Randomized controlled trial","Placebo","Bias"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Clinical significance","cat":"Research & evidence","pron":"KLIN-ih-kul sig-NIF-ih-kents","def":"The practical or meaningful importance of a treatment effect for patients or functioning, which is different from merely achieving statistical significance.","aliases":[],"related":["Statistical significance","Effect size","Minimal clinically important difference"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Cohort study","cat":"Research & evidence","pron":"KOH-hort STUD-ee","def":"An observational study that follows or compares groups defined by an exposure or characteristic to examine outcomes over time.","aliases":[],"related":["Observational study","Case-control study","Confounding"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Confidence interval","cat":"Research & evidence","pron":"KON-fih-dents IN-ter-vul","def":"A range of values around an estimate that reflects statistical uncertainty. A narrower interval generally indicates greater precision.","aliases":["CI"],"related":["Effect size","Statistical significance","Estimate"],"route":"","collections":["Research Literacy","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Confounding","cat":"Research & evidence","pron":"kun-FOUND-ing","def":"Distortion of an observed relationship because another factor is associated with both the exposure and the outcome.","aliases":["confounder"],"related":["Bias","Observational study","Causation"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Correlation","cat":"Research & evidence","pron":"kor-uh-LAY-shun","def":"A statistical relationship between two variables. Correlation alone does not prove that one variable causes the other.","aliases":[],"related":["Causation","Confounding","Observational study"],"route":"","collections":["Research Literacy"],"safety":"","confused":"Correlation is not the same as causation.","sources":[],"reviewed":"October 5, 2026"},{"term":"Effect size","cat":"Research & evidence","pron":"ee-FEKT size","def":"A quantitative measure of the magnitude of a difference or relationship in a study, helping show how large an effect may be rather than only whether it is statistically significant.","aliases":[],"related":["Clinical significance","Confidence interval","Meta-analysis"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Incidence","cat":"Research & evidence","pron":"IN-sih-dents","def":"The number or rate of new cases of a condition occurring in a population during a specified period.","aliases":[],"related":["Prevalence","Risk","Epidemiology"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Number needed to harm","cat":"Research & evidence","pron":"NUM-ber NEE-did to HARM","def":"The estimated number of people who would need to receive an exposure or treatment for one additional harmful outcome to occur compared with a control condition.","aliases":["NNH"],"related":["Number needed to treat","Absolute risk","Adverse event"],"route":"","collections":["Research Literacy","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Number needed to treat","cat":"Research & evidence","pron":"NUM-ber NEE-did to TREET","def":"The estimated number of people who need to receive a treatment for one additional person to benefit compared with a control condition over a specified time.","aliases":["NNT"],"related":["Number needed to harm","Absolute risk","Effect size"],"route":"","collections":["Research Literacy","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Observational study","cat":"Research & evidence","pron":"ob-zur-VAY-shun-ul STUD-ee","def":"A study in which researchers observe exposures and outcomes without randomly assigning participants to interventions.","aliases":[],"related":["Cohort study","Case-control study","Confounding"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Peer review","cat":"Research & evidence","pron":"PEER ree-VYOO","def":"Evaluation of a research manuscript or scholarly work by other experts before publication. Peer review can improve quality control but does not guarantee that a study is correct.","aliases":[],"related":["Preprint","Replication","Research quality"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Preprint","cat":"Research & evidence","pron":"PREE-print","def":"A research manuscript made publicly available before formal journal peer review. Findings may change during review and should be interpreted cautiously.","aliases":[],"related":["Peer review","Replication","Research quality"],"route":"","collections":["Research Literacy"],"safety":"Preprints have not completed journal peer review.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Prevalence","cat":"Research & evidence","pron":"PREV-uh-lents","def":"The proportion of a population that has a condition at a particular time or during a specified period.","aliases":[],"related":["Incidence","Epidemiology","Population"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Reliability","cat":"Research & evidence","pron":"ree-ly-uh-BIL-ih-tee","def":"The consistency or repeatability of a measurement, test, rating, or research result under defined conditions.","aliases":[],"related":["Validity","Measurement","Replication"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Replication","cat":"Research & evidence","pron":"rep-lih-KAY-shun","def":"Repeating a study or analysis to determine whether similar findings can be observed again.","aliases":[],"related":["Peer review","Reliability","Evidence"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Sensitivity","cat":"Research & evidence","pron":"sen-sih-TIV-ih-tee","def":"For a diagnostic or screening test, the proportion of people with the condition who are correctly identified as positive.","aliases":[],"related":["Specificity","Screening test","False negative"],"route":"","collections":["Research Literacy"],"safety":"","confused":"High sensitivity does not by itself prove a diagnosis.","sources":[],"reviewed":"October 5, 2026"},{"term":"Specificity","cat":"Research & evidence","pron":"spes-ih-FIS-ih-tee","def":"For a diagnostic or screening test, the proportion of people without the condition who are correctly identified as negative.","aliases":[],"related":["Sensitivity","Screening test","False positive"],"route":"","collections":["Research Literacy"],"safety":"","confused":"High specificity does not by itself establish diagnosis in an individual.","sources":[],"reviewed":"October 5, 2026"},{"term":"Statistical significance","cat":"Research & evidence","pron":"stuh-TIS-tih-kul sig-NIF-ih-kents","def":"A statistical finding suggesting that an observed result would be unlikely under a specified null model. It does not automatically mean the effect is large, important, or clinically meaningful.","aliases":[],"related":["Clinical significance","P value","Effect size"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Validity","cat":"Research & evidence","pron":"vuh-LID-ih-tee","def":"The extent to which a test, measure, or study supports the interpretation or conclusion it is intended to support.","aliases":[],"related":["Reliability","Measurement","Diagnostic accuracy"],"route":"","collections":["Research Literacy"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Caregiver burden","cat":"Family & caregiver","pron":"KAIR-giv-er BUR-den","def":"The emotional, physical, financial, social, or practical strain that can develop when supporting a person with significant health needs.","aliases":["caregiver strain"],"related":["Caregiver burnout","Respite care","Family psychoeducation"],"route":"family-caregiver.html","collections":["Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Caregiver burnout","cat":"Family & caregiver","pron":"KAIR-giv-er BURN-out","def":"Severe exhaustion, stress, or depletion related to prolonged caregiving demands. It can affect health and the ability to continue providing support.","aliases":[],"related":["Caregiver burden","Respite care","Self-care"],"route":"family-caregiver.html","collections":["Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Expressed emotion","cat":"Family & caregiver","pron":"ek-SPREST ee-MOH-shun","def":"A research term describing patterns of criticism, hostility, or emotional overinvolvement within close relationships. Higher expressed emotion has been associated with relapse risk in some serious mental illnesses.","aliases":["EE"],"related":["Family psychoeducation","Relapse prevention","Schizophrenia"],"route":"family-caregiver.html","collections":["Family & Caregiver","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Family accommodation","cat":"Family & caregiver","pron":"FAM-uh-lee uh-kom-uh-DAY-shun","def":"Ways family members may change their behavior to reduce a loved one's distress, such as participating in rituals or providing repeated reassurance. In OCD, excessive accommodation can unintentionally maintain symptoms.","aliases":[],"related":["OCD","Compulsion","ERP"],"route":"family-caregiver.html","collections":["Family & Caregiver"],"safety":"","confused":"This meaning is different from disability accommodation at work or school.","sources":[],"reviewed":"October 5, 2026"},{"term":"Respite care","cat":"Family & caregiver","pron":"RES-pit KAIR","def":"Short-term care or support intended to give a family caregiver a temporary break from ongoing caregiving responsibilities.","aliases":["caregiver respite"],"related":["Caregiver burden","Caregiver burnout","Community services"],"route":"family-caregiver.html","collections":["Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Health care proxy","cat":"Family & caregiver","pron":"HELTH KAIR PROK-see","def":"A person legally authorized under applicable law or an advance directive to make certain health-care decisions for another person when the required conditions are met.","aliases":["health care agent","medical power of attorney"],"related":["Advance directive","Capacity","Surrogate decision-maker"],"route":"crisis-legal.html","collections":["Family & Caregiver","Legal Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Surrogate decision-maker","cat":"Family & caregiver","pron":"SUR-uh-gut dih-SIZH-un MAY-ker","def":"A person authorized by law or legal document to make health-care decisions for someone who lacks the required decision-making capacity.","aliases":["surrogate"],"related":["Health care proxy","Capacity","Guardianship"],"route":"crisis-legal.html","collections":["Family & Caregiver","Legal Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Care coordination","cat":"Family & caregiver","pron":"KAIR koh-or-dih-NAY-shun","def":"Organizing communication and services across clinicians, hospitals, community programs, family supports, and other systems to reduce fragmentation.","aliases":[],"related":["Case management","Warm handoff","Discharge planning"],"route":"family-caregiver.html","collections":["Family & Caregiver","Hospital Words"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Interactive process","cat":"Work & school","pron":"in-ter-AK-tiv PRAH-sess","def":"In U.S. disability employment practice, the back-and-forth discussion between employer and employee used to identify effective reasonable accommodations when needed.","aliases":[],"related":["Reasonable accommodation","ADA","Essential function"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Essential function","cat":"Work & school","pron":"eh-SEN-shul FUNK-shun","def":"A fundamental duty of a job. Under U.S. disability law, reasonable accommodation can help a qualified employee perform essential functions but generally does not require removing them.","aliases":["essential job function"],"related":["Reasonable accommodation","Interactive process","ADA"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"IEP","cat":"Work & school","pron":"eye-ee-PEE","def":"Individualized Education Program, a written special-education plan for an eligible K–12 student under the Individuals with Disabilities Education Act.","aliases":["Individualized Education Program"],"related":["IDEA","Section 504","Special education"],"route":"life-guide.html","collections":["Work & School","Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Disability services","cat":"Work & school","pron":"dis-uh-BIL-ih-tee SUR-vuh-siz","def":"A college or university office or process that coordinates academic accommodations and access for eligible students with disabilities.","aliases":["accessibility services"],"related":["Reasonable accommodation","Section 504","Academic adjustment"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Academic adjustment","cat":"Work & school","pron":"ak-uh-DEM-ik uh-JUST-ment","def":"A modification or support in postsecondary education intended to provide equal access for a student with a disability, such as testing adjustments or accessible materials when appropriate.","aliases":["college accommodation"],"related":["Disability services","Section 504","Reasonable accommodation"],"route":"life-guide.html","collections":["Work & School"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Suicidal intent","cat":"Crisis & safety","pron":"soo-ih-SY-dul in-TENT","def":"The degree to which a person intends to act on suicidal thoughts. Intent is one important part of suicide risk assessment and must be considered with plan, means, timing, past behavior, and protective factors.","aliases":[],"related":["Suicidal ideation","Suicide plan","Suicide risk assessment"],"route":"crisis-legal.html","collections":["Crisis Terms"],"safety":"If a person intends to act on suicidal thoughts or cannot stay safe, seek immediate crisis or emergency help.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Suicide plan","cat":"Crisis & safety","pron":"SOO-ih-side plan","def":"Specific thinking about how, when, where, or under what circumstances a suicide attempt might occur. Greater specificity can increase concern and should be assessed with intent and access to means.","aliases":[],"related":["Suicidal intent","Lethal means","Suicide risk assessment"],"route":"crisis-legal.html","collections":["Crisis Terms"],"safety":"A suicide plan can signal high risk. Seek live professional help when safety is uncertain.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Lethal means","cat":"Crisis & safety","pron":"LEE-thul meenz","def":"Methods or objects that could be used to cause death, such as firearms or large quantities of medications. Reducing access during a suicidal crisis is an evidence-based safety strategy.","aliases":["means safety"],"related":["Safety plan","Suicide plan","Suicide prevention"],"route":"crisis-legal.html","collections":["Crisis Terms"],"safety":"If there is imminent danger, contact emergency services. Means-safety planning should prioritize immediate safety and lawful, practical steps.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"No-suicide contract","cat":"Crisis & safety","pron":"NOH SOO-ih-side KON-trakt","def":"An agreement in which a person promises not to attempt suicide. Such agreements are not a substitute for a real suicide risk assessment, safety plan, or emergency intervention when needed.","aliases":["safety contract","no-harm contract"],"related":["Safety plan","Suicide risk assessment","Suicidal ideation"],"route":"crisis-legal.html","collections":["Crisis Terms"],"safety":"Do not rely on a promise or contract as proof that someone is safe.","confused":"A collaborative safety plan is different from a no-suicide contract.","sources":[],"reviewed":"October 5, 2026"},{"term":"Duty to warn","cat":"Legal & systems","pron":"DYOO-tee to WARN","def":"A legal concept in some jurisdictions concerning clinician duties when a patient makes a serious threat toward an identifiable person. The exact duty varies by state law and professional context.","aliases":["duty to protect"],"related":["Confidentiality","Threat assessment","State law"],"route":"state-law.html","collections":["Legal Words"],"safety":"Legal duties vary by jurisdiction; use current state law and professional guidance.","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Confidentiality","cat":"Legal & systems","pron":"kon-fih-den-shee-AL-ih-tee","def":"The professional and legal obligation to protect private information, subject to applicable exceptions such as consent, treatment operations, legal requirements, or certain safety situations.","aliases":[],"related":["HIPAA","Release of information","Duty to warn"],"route":"family-caregiver.html","collections":["Legal Words","Family & Caregiver"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Insomnia disorder","cat":"Conditions","pron":"in-SOM-nee-uh dis-OR-der","def":"Persistent difficulty falling asleep, staying asleep, or obtaining restorative sleep despite adequate opportunity, causing daytime impairment.","aliases":["chronic insomnia"],"related":["Sleep hygiene","Circadian rhythm","Depression"],"route":"condition-guide.html","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Narcolepsy","cat":"Conditions","pron":"NAR-koh-lep-see","def":"A neurological sleep-wake disorder involving excessive daytime sleepiness and abnormal regulation of REM sleep, sometimes including cataplexy.","aliases":[],"related":["Hypersomnolence","Sleep disorder","Cataplexy"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Mild cognitive impairment","cat":"Conditions","pron":"MYLD KOG-nih-tiv im-PAIR-ment","def":"Measurable decline in one or more cognitive abilities that is greater than expected for age but does not yet substantially interfere with independent everyday functioning.","aliases":["MCI"],"related":["Dementia","MoCA","Neurocognitive disorder"],"route":"","collections":["Acronym Decoder"],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Neurocognitive disorder","cat":"Conditions","pron":"nur-oh-KOG-nih-tiv dis-OR-der","def":"A broad clinical category involving acquired decline in cognitive functioning from a previous level, with causes ranging from neurodegenerative disease to vascular, traumatic, substance-related, or other medical conditions.","aliases":[],"related":["Delirium","Dementia","Mild cognitive impairment"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"},{"term":"Sleep hygiene","cat":"General","pron":"SLEEP HY-jeen","def":"Habits and environmental practices intended to support healthy sleep, such as regular timing, light exposure, reducing disruptive substances, and creating a sleep-conducive environment.","aliases":[],"related":["Insomnia disorder","Circadian rhythm","Sleep"],"route":"","collections":[],"safety":"","confused":"","sources":[],"reviewed":"October 5, 2026"}];
